-- Targeted neutral triangle cable row review; retain manual edits and immutable histories.
BEGIN;
SELECT id FROM "Exercise" WHERE id='120f29ac-733c-478b-8aa9-a3f4c22f5e70' FOR UPDATE;
DO $$ BEGIN
 IF EXISTS (SELECT 1 FROM "Exercise" WHERE id='120f29ac-733c-478b-8aa9-a3f4c22f5e70' AND ("ownerUserId" IS NOT NULL OR name <> 'Remada Baixa no Cabo com Triângulo')) THEN RAISE EXCEPTION 'Pulldown identity changed; review manually'; END IF;
 IF EXISTS (SELECT 1 FROM "Exercise" e WHERE e.id='120f29ac-733c-478b-8aa9-a3f4c22f5e70' AND e."anatomyReview" IS NULL AND (EXISTS (SELECT 1 FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id AND NOT ((m."muscleGroup"='BACK' AND m.role='PRIMARY') OR (m."muscleGroup" IN ('BICEPS','FOREARMS','SHOULDERS') AND m.role='SECONDARY'))) OR (SELECT count(*) FROM "ExerciseMuscle" m WHERE m."exerciseId"=e.id)<>4)) THEN RAISE EXCEPTION 'Pulldown classification changed; review manually'; END IF;
END $$;
INSERT INTO "ExerciseMuscle" (id,"exerciseId","muscleGroup",role,"createdAt") SELECT gen_random_uuid()::text,e.id,g::"MuscleGroup",'SECONDARY'::"MuscleRole",CURRENT_TIMESTAMP FROM "Exercise" e CROSS JOIN (VALUES ('CORE')) groups(g) WHERE e.id='120f29ac-733c-478b-8aa9-a3f4c22f5e70' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL ON CONFLICT ("exerciseId","muscleGroup") DO NOTHING;
UPDATE "Exercise" e SET "anatomyReview"='{"version":"2026-11-13.1","reviewedAt":"2026-11-13T15:30:00.000Z","variant":"Remada baixa bilateral no cabo com triângulo, pegada neutra fechada, tronco estável e pés apoiados na plataforma.","aliases":["remada baixa no cabo com triângulo","remada baixa no triângulo","seated cable row with triangle"],"participants":[{"id":"LATISSIMUS_DORSI","label":"Latíssimo do dorso","muscleGroup":"BACK","role":"PRIMARY","aliases":["dorsal","grande dorsal","latissimus dorsi"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["PADOVAN_2025","OPENSTAX_UPPER"]},{"id":"TERES_MAJOR","label":"Redondo maior","muscleGroup":"BACK","role":"PRIMARY","aliases":["teres major"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"TRAPEZIUS","label":"Trapézio","muscleGroup":"BACK","role":"PRIMARY","aliases":["trapézio médio","trapézio inferior","trapezius"],"regions":[{"id":"TRAPEZIUS_TRANSVERSE","label":"Porção média do trapézio","aliases":["trapézio médio","porção transversa"]},{"id":"TRAPEZIUS_DESCENDING","label":"Porção superior do trapézio","aliases":["trapézio superior"]},{"id":"TRAPEZIUS_ASCENDING","label":"Porção inferior do trapézio","aliases":["trapézio inferior"]}],"emphasizedRegionIds":["TRAPEZIUS_TRANSVERSE"],"sourceIds":["PADOVAN_2025","OPENSTAX_UPPER"]},{"id":"RHOMBOIDS","label":"Romboides","muscleGroup":"BACK","role":"PRIMARY","aliases":["romboide maior","romboide menor"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"DELTOID_POSTERIOR","label":"Deltoide posterior","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["ombro posterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["PADOVAN_2025","OPENSTAX_UPPER"]},{"id":"INFRASPINATUS","label":"Infraespinal","muscleGroup":"SHOULDERS","role":"SECONDARY","aliases":["infraespinhoso","manguito rotador"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"BICEPS_BRACHII","label":"Bíceps braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["bíceps"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["PADOVAN_2025","OPENSTAX_UPPER"]},{"id":"BRACHIALIS","label":"Braquial","muscleGroup":"BICEPS","role":"SECONDARY","aliases":["braquial anterior"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"BRACHIORADIALIS","label":"Braquiorradial","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["braquiorradialis"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_SUPERFICIALIS","label":"Flexor superficial dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_DIGITORUM_PROFUNDUS","label":"Flexor profundo dos dedos","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["pegada"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"FLEXOR_CARPI_ULNARIS","label":"Flexor ulnar do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTENSOR_CARPI_RADIALIS_BREVIS","label":"Extensor radial curto do carpo","muscleGroup":"FOREARMS","role":"SECONDARY","aliases":["punho"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"ERECTOR_SPINAE","label":"Eretores da coluna","muscleGroup":"BACK","role":"SECONDARY","aliases":["eretor da espinha","estabilizadores do tronco"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["PADOVAN_2025","OPENSTAX_UPPER"]},{"id":"RECTUS_ABDOMINIS","label":"Reto abdominal","muscleGroup":"CORE","role":"SECONDARY","aliases":["abdômen","abdominais"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]},{"id":"EXTERNAL_OBLIQUE","label":"Oblíquo externo","muscleGroup":"CORE","role":"SECONDARY","aliases":["oblíquos"],"regions":[],"emphasizedRegionIds":[],"sourceIds":["OPENSTAX_UPPER"]}],"sources":[{"id":"PADOVAN_2025","title":"Padovan et al. — High-Density Surface Electromyography Excitation of Prime Movers in the Narrow vs. Wide Grip Seated Row Exercise (2025)","url":"https://doi.org/10.5114/jhk/209550","limitation":"14 homens treinados, 8RM, triângulo versus barra aberta; EMG por fase. Tronco fixo, joelhos levemente flexionados e triângulo ao abdômen. Diferenças agudas não medem hipertrofia nem definem anatomia individual ou ativação no avatar."},{"id":"VASCONCELOS_2023","title":"Vasconcelos et al. — Effect of Different Grip Position and Shoulder-Abduction Angle During the Seated Cable Row (2023)","url":"https://doi.org/10.47206/ijsc.v3i1.190","limitation":"11 homens e 10 mulheres, análise isométrica/dinâmica, pegadas e abdução do ombro. Não estabelece a combinação ideal entre pegada e amplitude, nem permite extrapolar resultados a toda máquina de remada."},{"id":"OPENSTAX_UPPER","title":"OpenStax Anatomy and Physiology 2e — Muscles of the Pectoral Girdle and Upper Limbs","url":"https://openstax.org/books/anatomy-and-physiology-2e/pages/11-5-muscles-of-the-pectoral-girdle-and-upper-limbs","limitation":"Anatomia funcional: adução/extensão do ombro, flexão do cotovelo, controle escapular e pegada. Papéis não medidos no estudo e estabilização do tronco são inferências anatômicas/editoriais, sem quantificação nesta variação."}],"notes":"Extensão do ombro e retração escapular: dorsal, redondo maior, romboides e trapézio médio são principais na representação. Porções superior/inferior do trapézio e demais sinergistas/estabilizadores aparecem mais claros, sem mudar a classificação primária do grupo. A ênfase média é funcional/anatômica, não um mapa regional de EMG. Braços e manguito coenvolvidos; pegada/core mantêm apoio e estabilidade. Tronco fixo, cotovelos próximos e triângulo ao abdômen. Não há isolamento ou intensidade medida; ângulos e tempos do rig são ilustrativos, sem otimização universal.","instructions":{"description":"Remada baixa bilateral na polia com triângulo e pegada neutra, palmas voltadas uma para a outra.","setup":"Sente-se no banco, apoie os pés na plataforma e mantenha os joelhos ligeiramente flexionados. Segure o triângulo com os braços alongados, coluna em posição confortável e tronco firme.","execution":"Puxe o triângulo em direção ao abdômen conduzindo os cotovelos próximos do tronco e permitindo o movimento das escápulas. Faça uma pausa breve e retorne com controle, alongando os braços sem embalar o corpo.","tips":"Mantenha os punhos alinhados aos antebraços, os pés apoiados e evite jogar o tronco para trás. Dorsal, redondo maior, trapézio e romboides atuam junto dos braços e estabilizadores. As cores são ilustrativas e não medem ativação ou esforço."}}'::jsonb,"updatedAt"=CURRENT_TIMESTAMP WHERE e.id='120f29ac-733c-478b-8aa9-a3f4c22f5e70' AND e."ownerUserId" IS NULL AND e."anatomyReview" IS NULL;
COMMIT;
